/*
 * JCS Business Suite Web
 * BusinessLogoStorageService.ts
 *
 * Firebase Storage service for:
 *
 * - Business Owner uploaded logos.
 * - Premium logos generated by Sofía.
 * - Upload progress.
 * - Download URL retrieval.
 * - Safe logo replacement.
 * - Logo deletion.
 *
 * Firestore writes and React state must not live here.
 */

import {
  FirebaseStorage,
  StorageError,
  deleteObject,
  getDownloadURL,
  getMetadata,
  getStorage,
  ref,
  uploadBytesResumable,
} from "firebase/storage";

import {
  BUSINESS_LOGO_OUTPUT_MIME_TYPE,
  buildGeneratedBusinessLogoStoragePath,
  buildUploadedBusinessLogoStoragePath,
} from "./BusinessLogoConstants";

import {
  createBusinessLogoID,
} from "./BusinessLogoTypes";

import type {
  BusinessLogoSource,
} from "./BusinessLogoTypes";

// MARK: - Upload Input

export interface UploadBusinessLogoToStorageInput {
  businessID: string;
  ownerUID: string;
  createdByUID: string;

  businessName: string;

  source: Exclude<
    BusinessLogoSource,
    "default"
  >;

  file: File;

  /**
   * Optional ID already assigned by the calling workflow.
   * A new ID is created when omitted.
   */
  logoID?: string;

  /**
   * Generated and uploaded business logos normally preserve
   * their original colors.
   */
  supportsAccentColor?: boolean;

  creativeBrief?: string;
  promptUsed?: string;

  onProgress?: (
    progress: BusinessLogoUploadProgress,
  ) => void;

  /**
   * Optional injected Storage instance for tests or
   * applications using multiple Firebase apps.
   */
  storage?: FirebaseStorage;
}

// MARK: - Upload Progress

export interface BusinessLogoUploadProgress {
  bytesTransferred: number;
  totalBytes: number;
  progressPercent: number;
  state:
    | "running"
    | "paused"
    | "success";
}

// MARK: - Upload Result

export interface UploadedBusinessLogoStorageResult {
  logoID: string;

  businessID: string;
  ownerUID: string;
  createdByUID: string;

  source: Exclude<
    BusinessLogoSource,
    "default"
  >;

  storagePath: string;
  downloadURL: string;

  originalFileName: string;
  storedFileName: string;
  mimeType: string;
  sizeBytes: number;

  supportsAccentColor: boolean;

  creativeBrief: string;
  promptUsed: string;
}

// MARK: - Stored File Information

export interface BusinessLogoStorageMetadata {
  storagePath: string;

  contentType: string;
  sizeBytes: number;

  businessID: string;
  ownerUID: string;
  createdByUID: string;

  source: string;
  logoID: string;
}

// MARK: - Upload

/**
 * Uploads a definitive business logo to Firebase Storage.
 *
 * The file passed here should already be validated and normalized
 * by BusinessLogoDomain.ts.
 */
export async function uploadBusinessLogoToStorage(
  input: UploadBusinessLogoToStorageInput,
): Promise<UploadedBusinessLogoStorageResult> {
  const normalizedInput =
    normalizeUploadInput(input);

  const storage =
    input.storage ?? getStorage();

  const storagePath =
    buildStoragePath({
      businessID:
        normalizedInput.businessID,

      logoID:
        normalizedInput.logoID,

      source:
        normalizedInput.source,
    });

  const storageReference =
    ref(storage, storagePath);

  const storedFileName =
    getFinalPathComponent(storagePath);

  const uploadTask =
    uploadBytesResumable(
      storageReference,
      normalizedInput.file,
      {
        contentType:
          BUSINESS_LOGO_OUTPUT_MIME_TYPE,

        cacheControl:
          "public,max-age=3600",

        customMetadata: {
          logoID:
            normalizedInput.logoID,

          businessID:
            normalizedInput.businessID,

          ownerUID:
            normalizedInput.ownerUID,

          createdByUID:
            normalizedInput.createdByUID,

          businessName:
            normalizedInput.businessName,

          source:
            normalizedInput.source,

          supportsAccentColor:
            String(
              normalizedInput
                .supportsAccentColor,
            ),

          originalFileName:
            normalizedInput.file.name,

          creativeBrief:
            truncateMetadataValue(
              normalizedInput.creativeBrief,
            ),

          promptUsed:
            truncateMetadataValue(
              normalizedInput.promptUsed,
            ),

          uploadedAtISO:
            new Date().toISOString(),
        },
      },
    );

  await waitForBusinessLogoUpload({
    uploadTask,

    onProgress:
      normalizedInput.onProgress,
  });

  const downloadURL =
    await getDownloadURL(
      uploadTask.snapshot.ref,
    );

  return {
    logoID:
      normalizedInput.logoID,

    businessID:
      normalizedInput.businessID,

    ownerUID:
      normalizedInput.ownerUID,

    createdByUID:
      normalizedInput.createdByUID,

    source:
      normalizedInput.source,

    storagePath:
      uploadTask.snapshot.ref.fullPath,

    downloadURL,

    originalFileName:
      normalizedInput.file.name,

    storedFileName,

    mimeType:
      normalizedInput.file.type ||
      BUSINESS_LOGO_OUTPUT_MIME_TYPE,

    sizeBytes:
      normalizedInput.file.size,

    supportsAccentColor:
      normalizedInput.supportsAccentColor,

    creativeBrief:
      normalizedInput.creativeBrief,

    promptUsed:
      normalizedInput.promptUsed,
  };
}

// MARK: - Uploaded Logo Convenience

export async function uploadOwnerSelectedBusinessLogo(
  input: Omit<
    UploadBusinessLogoToStorageInput,
    "source"
  >,
): Promise<UploadedBusinessLogoStorageResult> {
  return uploadBusinessLogoToStorage({
    ...input,

    source:
      "uploaded",

    /**
     * A customer-uploaded logo preserves its original colors
     * unless a later explicit template workflow proves that
     * it supports accent-color rendering.
     */
    supportsAccentColor:
      input.supportsAccentColor === true,
  });
}

// MARK: - Generated Logo Convenience

export async function uploadSofiaGeneratedBusinessLogo(
  input: Omit<
    UploadBusinessLogoToStorageInput,
    "source"
  >,
): Promise<UploadedBusinessLogoStorageResult> {
  return uploadBusinessLogoToStorage({
    ...input,

    source:
      "ai-generated",

    /**
     * Sofía-generated premium logos normally keep their
     * designed color palette.
     */
    supportsAccentColor:
      input.supportsAccentColor === true,
  });
}

// MARK: - Download URL

export async function getBusinessLogoDownloadURL(
  storagePath: string,
  storage?: FirebaseStorage,
): Promise<string> {
  const cleanStoragePath =
    normalizeStoragePath(storagePath);

  if (!cleanStoragePath) {
    throw new BusinessLogoStorageServiceError(
      "missing-storage-path",
      "The business logo Storage path is missing.",
    );
  }

  try {
    return await getDownloadURL(
      ref(
        storage ?? getStorage(),
        cleanStoragePath,
      ),
    );
  } catch (error) {
    throw mapBusinessLogoStorageError(
      error,
      "The business logo URL could not be loaded.",
    );
  }
}

// MARK: - Metadata

export async function readBusinessLogoStorageMetadata(
  storagePath: string,
  storage?: FirebaseStorage,
): Promise<BusinessLogoStorageMetadata> {
  const cleanStoragePath =
    normalizeStoragePath(storagePath);

  if (!cleanStoragePath) {
    throw new BusinessLogoStorageServiceError(
      "missing-storage-path",
      "The business logo Storage path is missing.",
    );
  }

  try {
    const metadata =
      await getMetadata(
        ref(
          storage ?? getStorage(),
          cleanStoragePath,
        ),
      );

    return {
      storagePath:
        metadata.fullPath,

      contentType:
        metadata.contentType ??
        BUSINESS_LOGO_OUTPUT_MIME_TYPE,

      sizeBytes:
        Number(metadata.size) || 0,

      businessID:
        metadata.customMetadata
          ?.businessID ?? "",

      ownerUID:
        metadata.customMetadata
          ?.ownerUID ?? "",

      createdByUID:
        metadata.customMetadata
          ?.createdByUID ?? "",

      source:
        metadata.customMetadata
          ?.source ?? "",

      logoID:
        metadata.customMetadata
          ?.logoID ?? "",
    };
  } catch (error) {
    throw mapBusinessLogoStorageError(
      error,
      "The business logo metadata could not be loaded.",
    );
  }
}

// MARK: - Existence

export async function businessLogoExistsInStorage(
  storagePath: string,
  storage?: FirebaseStorage,
): Promise<boolean> {
  const cleanStoragePath =
    normalizeStoragePath(storagePath);

  if (!cleanStoragePath) {
    return false;
  }

  try {
    await getMetadata(
      ref(
        storage ?? getStorage(),
        cleanStoragePath,
      ),
    );

    return true;
  } catch (error) {
    if (
      isStorageObjectNotFoundError(error)
    ) {
      return false;
    }

    throw mapBusinessLogoStorageError(
      error,
      "The business logo could not be checked.",
    );
  }
}

// MARK: - Delete

export async function deleteBusinessLogoFromStorage(
  storagePath: string,
  storage?: FirebaseStorage,
): Promise<void> {
  const cleanStoragePath =
    normalizeStoragePath(storagePath);

  if (!cleanStoragePath) {
    return;
  }

  assertSafeBusinessLogoStoragePath(
    cleanStoragePath,
  );

  try {
    await deleteObject(
      ref(
        storage ?? getStorage(),
        cleanStoragePath,
      ),
    );
  } catch (error) {
    /**
     * Deleting an already missing file should be treated
     * as a successful cleanup.
     */
    if (
      isStorageObjectNotFoundError(error)
    ) {
      return;
    }

    throw mapBusinessLogoStorageError(
      error,
      "The business logo could not be deleted.",
    );
  }
}

// MARK: - Replacement Cleanup

/**
 * Deletes the previous logo only after the new logo and its
 * Firestore record have been saved successfully.
 *
 * Call this function after completing the new logo transaction.
 */
export async function deleteReplacedBusinessLogo(
  input: {
    previousStoragePath: string;
    newStoragePath: string;
    storage?: FirebaseStorage;
  },
): Promise<void> {
  const previousStoragePath =
    normalizeStoragePath(
      input.previousStoragePath,
    );

  const newStoragePath =
    normalizeStoragePath(
      input.newStoragePath,
    );

  if (!previousStoragePath) {
    return;
  }

  if (
    previousStoragePath ===
    newStoragePath
  ) {
    return;
  }

  await deleteBusinessLogoFromStorage(
    previousStoragePath,
    input.storage,
  );
}

// MARK: - Multiple Cleanup

export async function deleteBusinessLogosFromStorage(
  input: {
    storagePaths: string[];
    preservedStoragePath?: string;
    storage?: FirebaseStorage;
  },
): Promise<void> {
  const preservedStoragePath =
    normalizeStoragePath(
      input.preservedStoragePath ?? "",
    );

  const uniqueStoragePaths =
    Array.from(
      new Set(
        input.storagePaths
          .map(normalizeStoragePath)
          .filter(Boolean),
      ),
    );

  const deletions =
    uniqueStoragePaths
      .filter(
        (storagePath) =>
          storagePath !==
          preservedStoragePath,
      )
      .map(
        async (storagePath) => {
          try {
            await deleteBusinessLogoFromStorage(
              storagePath,
              input.storage,
            );
          } catch (error) {
            console.warn(
              "Business logo cleanup failed:",
              storagePath,
              error,
            );
          }
        },
      );

  await Promise.all(deletions);
}

// MARK: - Upload Promise

interface WaitForBusinessLogoUploadInput {
  uploadTask: ReturnType<
    typeof uploadBytesResumable
  >;

  onProgress?: (
    progress: BusinessLogoUploadProgress,
  ) => void;
}

function waitForBusinessLogoUpload(
  input: WaitForBusinessLogoUploadInput,
): Promise<void> {
  return new Promise(
    (resolve, reject) => {
      input.uploadTask.on(
        "state_changed",

        (snapshot) => {
          const totalBytes =
            snapshot.totalBytes;

          const bytesTransferred =
            snapshot.bytesTransferred;

          const progressPercent =
            totalBytes > 0
              ? Math.min(
                  Math.max(
                    Math.round(
                      (
                        bytesTransferred /
                        totalBytes
                      ) * 100,
                    ),
                    0,
                  ),
                  100,
                )
              : 0;

          input.onProgress?.({
            bytesTransferred,
            totalBytes,
            progressPercent,
            state:
              snapshot.state === "paused"
                ? "paused"
                : "running",
          });
        },

        (error) => {
          reject(
            mapBusinessLogoStorageError(
              error,
              "The business logo upload failed.",
            ),
          );
        },

        () => {
          input.onProgress?.({
            bytesTransferred:
              input.uploadTask.snapshot
                .bytesTransferred,

            totalBytes:
              input.uploadTask.snapshot
                .totalBytes,

            progressPercent:
              100,

            state:
              "success",
          });

          resolve();
        },
      );
    },
  );
}

// MARK: - Input Normalization

interface NormalizedUploadInput {
  logoID: string;

  businessID: string;
  ownerUID: string;
  createdByUID: string;

  businessName: string;

  source: Exclude<
    BusinessLogoSource,
    "default"
  >;

  file: File;

  supportsAccentColor: boolean;

  creativeBrief: string;
  promptUsed: string;

  onProgress?: (
    progress: BusinessLogoUploadProgress,
  ) => void;
}

function normalizeUploadInput(
  input: UploadBusinessLogoToStorageInput,
): NormalizedUploadInput {
  const businessID =
    input.businessID.trim();

  const ownerUID =
    input.ownerUID.trim();

  const createdByUID =
    input.createdByUID.trim();

  const businessName =
    input.businessName
      .trim()
      .replace(/\s+/g, " ")
      .slice(0, 160);

  if (!businessID) {
    throw new BusinessLogoStorageServiceError(
      "missing-business-id",
      "The business ID is required before uploading a logo.",
    );
  }

  if (!ownerUID) {
    throw new BusinessLogoStorageServiceError(
      "missing-owner-uid",
      "The Business Owner identity is required before uploading a logo.",
    );
  }

  if (
    !(input.file instanceof File)
  ) {
    throw new BusinessLogoStorageServiceError(
      "invalid-file",
      "Choose a valid business logo image.",
    );
  }

  if (
    input.file.type !==
    BUSINESS_LOGO_OUTPUT_MIME_TYPE
  ) {
    throw new BusinessLogoStorageServiceError(
      "invalid-file-type",
      "The business logo must be normalized to PNG before upload.",
    );
  }

  if (
    input.file.size <= 0
  ) {
    throw new BusinessLogoStorageServiceError(
      "empty-file",
      "The business logo file is empty.",
    );
  }

  const source =
    input.source === "ai-generated"
      ? "ai-generated"
      : "uploaded";

  return {
    logoID:
      input.logoID?.trim() ||
      createBusinessLogoID(),

    businessID,
    ownerUID,
    createdByUID,

    businessName:
      businessName ||
      "New Business",

    source,

    file:
      input.file,

    supportsAccentColor:
      input.supportsAccentColor === true,

    creativeBrief:
      input.creativeBrief
        ?.trim() ?? "",

    promptUsed:
      input.promptUsed
        ?.trim() ?? "",

    onProgress:
      input.onProgress,
  };
}

// MARK: - Paths

function buildStoragePath(
  input: {
    businessID: string;
    logoID: string;
    source: Exclude<
      BusinessLogoSource,
      "default"
    >;
  },
): string {
  if (
    input.source === "ai-generated"
  ) {
    return buildGeneratedBusinessLogoStoragePath(
      input.businessID,
      input.logoID,
    );
  }

  return buildUploadedBusinessLogoStoragePath(
    input.businessID,
    input.logoID,
  );
}

function normalizeStoragePath(
  storagePath: string,
): string {
  return storagePath
    .trim()
    .replace(/^\/+|\/+$/g, "")
    .replace(/\/{2,}/g, "/");
}

function getFinalPathComponent(
  storagePath: string,
): string {
  return (
    normalizeStoragePath(storagePath)
      .split("/")
      .pop() ?? ""
  );
}

function assertSafeBusinessLogoStoragePath(
  storagePath: string,
): void {
  const pathParts =
    normalizeStoragePath(storagePath)
      .split("/");

  const isSafe =
    pathParts.length >= 5 &&
    pathParts[0] === "businesses" &&
    Boolean(pathParts[1]) &&
    pathParts[2] === "branding" &&
    Boolean(pathParts[3]) &&
    Boolean(pathParts[4]);

  if (!isSafe) {
    throw new BusinessLogoStorageServiceError(
      "unsafe-storage-path",
      "The logo Storage path is not a valid JCS business branding path.",
    );
  }
}

// MARK: - Metadata Helpers

function truncateMetadataValue(
  value: string,
): string {
  return value
    .trim()
    .replace(/\s+/g, " ")
    .slice(0, 1_000);
}

// MARK: - Error Handling

export class BusinessLogoStorageServiceError
  extends Error {
  readonly code: string;

  constructor(
    code: string,
    message: string,
  ) {
    super(message);

    this.name =
      "BusinessLogoStorageServiceError";

    this.code =
      code;
  }
}

function mapBusinessLogoStorageError(
  error: unknown,
  fallbackMessage: string,
): BusinessLogoStorageServiceError {
  if (
    error instanceof
    BusinessLogoStorageServiceError
  ) {
    return error;
  }

  const storageError =
    error as Partial<StorageError>;

  switch (storageError.code) {
    case "storage/unauthorized":
      return new BusinessLogoStorageServiceError(
        "unauthorized",
        "You do not have permission to change this business logo.",
      );

    case "storage/unauthenticated":
      return new BusinessLogoStorageServiceError(
        "unauthenticated",
        "Sign in again before changing the business logo.",
      );

    case "storage/canceled":
      return new BusinessLogoStorageServiceError(
        "upload-canceled",
        "The business logo upload was canceled.",
      );

    case "storage/retry-limit-exceeded":
      return new BusinessLogoStorageServiceError(
        "retry-limit-exceeded",
        "The logo upload took too long. Check the connection and try again.",
      );

    case "storage/quota-exceeded":
      return new BusinessLogoStorageServiceError(
        "quota-exceeded",
        "Firebase Storage has reached its current quota.",
      );

    case "storage/object-not-found":
      return new BusinessLogoStorageServiceError(
        "object-not-found",
        "The requested business logo no longer exists.",
      );

    case "storage/invalid-checksum":
      return new BusinessLogoStorageServiceError(
        "invalid-checksum",
        "The uploaded logo did not pass the integrity check.",
      );

    case "storage/invalid-argument":
      return new BusinessLogoStorageServiceError(
        "invalid-argument",
        "The business logo upload contains invalid information.",
      );

    case "storage/unknown":
      return new BusinessLogoStorageServiceError(
        "unknown",
        fallbackMessage,
      );

    default:
      return new BusinessLogoStorageServiceError(
        "storage-error",
        error instanceof Error &&
        error.message.trim()
          ? error.message
          : fallbackMessage,
      );
  }
}

function isStorageObjectNotFoundError(
  error: unknown,
): boolean {
  const storageError =
    error as Partial<StorageError>;

  return (
    storageError.code ===
    "storage/object-not-found"
  );
}